// src/pages/Home.jsx
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Input from "../components/common/Input";
import Button from "../components/common/Button";
import styles from "../Home.module.css";
import eveVideo from "../assets/eve_sdm_talk.mp4";
import { introText } from "../constants/sdm";

const Home = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false); // 新增：暫停狀態
  const [formData, setFormData] = useState({ userName: "", birthday: "" });

  // 1. 關鍵修正：將外層 Layout 預設的 Avatar 與標題清空隱藏，完全交給獨立卡片呈現
  // src/pages/Home.jsx 內部的 useEffect 修改

  useEffect(() => {
    // 關鍵修正：直接給 null，強制外層 Layout 完全不渲染頂部大頭貼與標題區塊
    setHeroData(null);

    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [setHeroData]);

  // 🔊 核心：連接語音與影片同步的處理函式
  const handlePlaySpeech = (rawText) => {
    if (!window.speechSynthesis || !videoRef.current || !rawText) return;

    // 先重設所有狀態
    window.speechSynthesis.cancel();

    // 清洗台詞：把 introText 裡面的 <p>、<strong> 等 HTML 標籤過濾掉，只留純文字
    const pureText = rawText.replace(/<[^>]*>/g, "").trim();

    const utterance = new SpeechSynthesisUtterance(pureText);
    utterance.lang = "zh-TW"; // 設定台灣中文
    utterance.rate = 1.0; // 語速

    // 🎬 當語音「真正開始發聲」的那一刻，影片才開始動
    utterance.onstart = () => {
      setIsPlaying(true);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.muted = true; // 靜音影片本身
        videoRef.current
          .play()
          .catch((err) => console.log("影片播放受阻：", err));
      }
    };

    // 🛑 當語音「唸完」的那一瞬間，影片立刻停下，嘴巴閉上
    utterance.onend = () => {
      setIsPlaying(false);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0; // 讓影片回到最初始閉嘴狀態
      }
    };

    utterance.onerror = () => {
      setIsPlaying(false);
      setIsPaused(false);
      if (videoRef.current) videoRef.current.pause();
    };

    // 執行發聲
    window.speechSynthesis.speak(utterance);
  };

  // ⏸️ 暫停 / 恢復 / 重新播放 切換控制邏輯
  const handleTogglePlay = (e) => {
    e.stopPropagation(); // 防止干擾

    if (!window.speechSynthesis) return;

    if (isPlaying && !isPaused) {
      // 執行暫停
      window.speechSynthesis.pause();
      if (videoRef.current) videoRef.current.pause();
      setIsPaused(true);
    } else if (isPlaying && isPaused) {
      // 恢復播放
      window.speechSynthesis.resume();
      if (videoRef.current) {
        videoRef.current.play().catch((err) => console.log(err));
      }
      setIsPaused(false);
    } else {
      // 從頭開始播放引言
      handlePlaySpeech(introText);
    }
  };

  const handleStart = () => {
    if (!formData.userName || !formData.birthday) {
      alert("請填寫完整資料後再開始");
      return;
    }
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    if (videoRef.current) videoRef.current.pause();

    setAllAnswers((prev) => ({
      ...prev,
      userName: formData.userName,
      birthday: formData.birthday,
    }));
    navigate("/selection");
  };

  return (
    <div className={styles.pageContainer}>
      {/* 獨立一體化大卡片 */}
      <div className={styles.interactiveCard}>
        {/* 上半部：小幫手大畫面不遮擋區 */}
        <div className={styles.videoSection}>
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            webkit-playsinline="true"
            preload="auto"
            loop
            className={styles.theatreVideo}
          />

          {/* 語音狀態小指示燈標籤 */}
          {isPlaying && (
            <div className={styles.audioBadge}>
              <span
                className={isPaused ? styles.audioDotPaused : styles.audioDot}
              ></span>
              {isPaused ? "已暫停引言" : "小幫手引導中..."}
            </div>
          )}

          {/* 右下角懸浮播放/暫停按鈕 */}
          <button className={styles.controlBtn} onClick={handleTogglePlay}>
            {isPlaying && !isPaused ? "⏸ 暫停說明" : "▶️ 播放說明"}
          </button>
        </div>

        {/* 下半部：表單內容區 */}
        <div className={styles.contentSection}>
          <div className={styles.inputWrapper}>
            <Input
              label="請輸入您的姓名"
              name="userName"
              value={formData.userName}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, userName: e.target.value }))
              }
            />
            <Input
              label="請輸入您的出生年月日"
              type="date"
              name="birthday"
              value={formData.birthday}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, birthday: e.target.value }))
              }
            />
          </div>

          <div className={styles.buttonWrapper}>
            <Button onClick={handleStart} fullWidth>
              開始使用 ➔
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
